#include "nussinov.h"

static inline int match_score(char a, char b) {
    if ((a == 'A' && (b == 'T' || b == 'U')) ||
        ((a == 'T' || a == 'U') && b == 'A') ||
        (a == 'G' && b == 'C') ||
        (a == 'C' && b == 'G'))
        return 1;
    else
        return 0;
}

void kernel_nussinov(char seq[60], int table[60][60]) {
    const int N = 60;

    // Initialize table all to zero
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            table[i][j] = 0;
        }
    }

    for (int len = 1; len < N; len++) {
        for (int i = 0; i < N - len; i++) {
            int j = i + len;

            int best = table[i + 1][j];                    // case 1
            int value = table[i][j - 1];                   // case 2
            if (value > best) best = value;

            value = table[i + 1][j - 1] + match_score(seq[i], seq[j]); // case 3
            if (value > best) best = value;

            // case 4
            for (int k = i + 1; k < j; k++) {
                value = table[i][k] + table[k + 1][j];
                if (value > best) best = value;
            }

            table[i][j] = best;
        }
    }
}
```

