void kernel_nussinov(char seq[60], int table[60][60]) {
    // initialize table
    for (int i = 0; i < 60; i++) {
        for (int j = 0; j < 60; j++) {
            table[i][j] = 0;
        }
    }

    // compute DP bottom-up
    for (int i = 59; i >= 0; i--) {
        for (int j = 0; j < 60; j++) {
            if (j < i) {
                continue;
            }
            if (i == j) {
                table[i][j] = 0;
                continue;
            }
            int max_val = table[i + 1][j];
            if (table[i][j - 1] > max_val) {
                max_val = table[i][j - 1];
            }
            int score = is_complementary(seq[i], seq[j]);
            int val = table[i + 1][j - 1] + score;
            if (val > max_val) {
                max_val = val;
            }
            for (int k = 0; k < 60; k++) {
                if (k > i && k < j) {
                    int split = table[i][k] + table[k + 1][j];
                    if (split > max_val) {
                        max_val = split;
                    }
                }
            }
            table[i][j] = max_val;
        }
    }
}

